+func TestLookup(t *testing.T) {
+	a := &Archive{
+		Files: []File{
+			{"foo.txt", []byte("hello")},
+			{"bar.txt", []byte("world")},
+		},
+	}
+
+	// Found
+	f, ok := a.Lookup("foo.txt")
+	if !ok || f == nil || f.Name != "foo.txt" {
+		t.Fatalf("Lookup(foo.txt) = %v, %v; want non-nil, true", f, ok)
+	}
+
+	// Not found
+	f, ok = a.Lookup("nope.txt")
+	if ok || f != nil {
+		t.Fatalf("Lookup(nope.txt) = %v, %v; want nil, false", f, ok)
+	}
